import * as THREE from './vendor/three.module.js';
const positions={exterior:[11,5.7,26],garden:[4,2.8,20],lobby:[0,2.4,5.6],classroom:[0,2.2,7.5],corridor:[0,2.2,7.5],office:[0,2.2,7.5],lesson:[0,2.2,7.5],staff:[0,2.2,7.5]};
export async function createPanorama(onHotspot){
const host=document.querySelector('#world'),spotLayer=document.querySelector('#hotspots');
const canvas=document.createElement('canvas');canvas.setAttribute('aria-hidden','true');host.append(canvas);const ctx=canvas.getContext('2d',{alpha:false});let yaw=0,pitch=0,fov=59,drag=null,current='exterior',spots=[],pending=false,faces=null,frame=null;
const camera=new THREE.PerspectiveCamera(fov,innerWidth/innerHeight,.1,250);
const ns='http://www.w3.org/2000/svg';const signLayer=document.createElementNS(ns,'svg');signLayer.classList.add('world-signs');signLayer.setAttribute('aria-hidden','true');host.append(signLayer);
const signData=await fetch('signs.json?v=2').then(r=>{if(!r.ok)throw new Error('Sign data unavailable');return r.json()});let sceneSigns=[];
function mountSigns(name){signLayer.replaceChildren();sceneSigns=(signData[name]||[]).map(original=>{const branch=name==='lobby'&&Math.abs(original.w-2.8)<.01;const sign=branch?{...original,size:136,lines:[original.lines[0].replace(/ ҚҰҚЫҚ$/,''),'ҚҰҚЫҚ']}:original;const width=1536,height=width*sign.h/sign.w,lineGap=branch?1.12:1.42;const el=document.createElementNS(ns,'g');el.style.visibility='hidden';const bg=document.createElementNS(ns,'polygon');bg.setAttribute('fill',sign.bg);el.append(bg);const texts=sign.lines.map((line,i)=>{const text=document.createElementNS(ns,'text');text.textContent=line;text.setAttribute('fill',sign.fg);text.setAttribute('text-anchor','middle');text.setAttribute('dominant-baseline','middle');text.setAttribute('font-family','Manrope,Arial');text.setAttribute('font-weight','700');text.setAttribute('font-size',sign.size);el.append(text);return{el:text,t:.5+(i-(sign.lines.length-1)/2)*sign.size*lineGap/height}});signLayer.append(el);return{...sign,el,bg,texts,width,height,points:sign.corners.map(p=>new THREE.Vector3(...p))}})}
function projectSigns(){signLayer.setAttribute('viewBox',`0 0 ${innerWidth} ${innerHeight}`);const forward=camera.getWorldDirection(new THREE.Vector3());const project=p=>{const q=p.clone().project(camera);return{x:(q.x*.5+.5)*innerWidth,y:(-q.y*.5+.5)*innerHeight}};for(const sign of sceneSigns){const [tl,tr,br,bl]=sign.points,v=sign.points.map(p=>p.clone().sub(camera.position));const normal=tr.clone().sub(tl).cross(bl.clone().sub(tl));if(v.some(p=>p.dot(forward)<.2)||normal.dot(v[0])<0){sign.el.style.visibility='hidden';continue}const corners=sign.points.map(project);if(corners.every(p=>p.x<-100)||corners.every(p=>p.x>innerWidth+100)||corners.every(p=>p.y<-100)||corners.every(p=>p.y>innerHeight+100)){sign.el.style.visibility='hidden';continue}sign.bg.setAttribute('points',corners.map(p=>`${p.x},${p.y}`).join(' '));for(const text of sign.texts){const left=tl.clone().lerp(bl,text.t),right=tr.clone().lerp(br,text.t),center=left.clone().lerp(right,.5),screen=project(center),pLeft=project(left),pRight=project(right),vertical=bl.clone().sub(tl).add(br.clone().sub(tr)).multiplyScalar(.5/sign.height),bottom=project(center.clone().add(vertical));text.el.setAttribute('transform',`matrix(${(pRight.x-pLeft.x)/sign.width} ${(pRight.y-pLeft.y)/sign.width} ${bottom.x-screen.x} ${bottom.y-screen.y} ${screen.x} ${screen.y})`)}sign.el.style.visibility='visible'}}
const faceNames=['front','back','left','right','up','down'];const cache=new Map();
async function loadScene(name){if(cache.has(name))return cache.get(name);const promise=Promise.all(faceNames.map(async face=>{const img=new Image();img.src=`panoramas/${innerWidth<700?'mobile/':''}${name}-${face}.webp?v=2`;await img.decode();const off=document.createElement('canvas');off.width=img.naturalWidth;off.height=img.naturalHeight;const c=off.getContext('2d',{willReadFrequently:true});c.drawImage(img,0,0);return {data:c.getImageData(0,0,off.width,off.height).data,size:off.width}})).catch(error=>{cache.delete(name);throw error});cache.set(name,promise);if(cache.size>2){const oldest=cache.keys().next().value;if(oldest!==name)cache.delete(oldest)}return promise}
function render(){if(!faces)return;const scale=drag?Math.min(1,850/innerWidth):Math.min(devicePixelRatio||1,2,2400/innerWidth);const w=Math.round(innerWidth*scale),h=Math.round(innerHeight*scale);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;frame=ctx.createImageData(w,h)}if(!frame)frame=ctx.createImageData(w,h);const out=frame.data,f=h/(2*Math.tan(fov*Math.PI/360)),cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),data=faces.map(v=>v.data),last=faces[0].size-1,size=faces[0].size;let index=0;
for(let py=0;py<h;py++){const vy=-(py-h/2)/f,yp=vy*cp+sp,zp=vy*sp-cp;for(let px=0;px<w;px++){const vx=(px-w/2)/f,x=cy*vx-sy*zp,y=yp,z=sy*vx+cy*zp,ax=Math.abs(x),ay=Math.abs(y),az=Math.abs(z);let side,u,v;if(az>=ax&&az>=ay){if(z<0){side=0;u=x/az}else{side=1;u=-x/az}v=-y/az}else if(ax>=ay){if(x<0){side=2;u=-z/ax}else{side=3;u=z/ax}v=-y/ax}else{if(y>0){side=4;u=x/ay;v=-z/ay}else{side=5;u=x/ay;v=z/ay}}const tx=Math.max(0,Math.min(last,(u+1)*.5*last)),ty=Math.max(0,Math.min(last,(v+1)*.5*last)),ix=tx|0,iy=ty|0,fx=tx-ix,fy=ty-iy,i00=(iy*size+ix)*4,i10=(iy*size+Math.min(last,ix+1))*4,i01=(Math.min(last,iy+1)*size+ix)*4,i11=(Math.min(last,iy+1)*size+Math.min(last,ix+1))*4,src=data[side],w00=(1-fx)*(1-fy),w10=fx*(1-fy),w01=(1-fx)*fy,w11=fx*fy;for(let c=0;c<3;c++)out[index++]=src[i00+c]*w00+src[i10+c]*w10+src[i01+c]*w01+src[i11+c]*w11;out[index++]=255}}ctx.putImageData(frame,0,0);
camera.rotation.order='YXZ';camera.rotation.set(pitch,-yaw,0);camera.aspect=innerWidth/innerHeight;camera.fov=fov;camera.updateProjectionMatrix();camera.updateMatrixWorld();projectSigns();const info=document.querySelector('#intro:not([hidden]),#sceneCard:not([hidden])')?.getBoundingClientRect();for(const spot of spots){const v=spot.pos.clone().project(camera),forward=spot.pos.clone().sub(camera.position).dot(camera.getWorldDirection(new THREE.Vector3()))>0;const sx=(v.x*.5+.5)*innerWidth,sy=(-v.y*.5+.5)*innerHeight,overlaps=info&&sx>info.left-35&&sx<info.right+35&&sy>info.top-40&&sy<info.bottom+40;const visible=forward&&Math.abs(v.x)<1.1&&Math.abs(v.y)<1.1&&!overlaps;spot.el.style.display=visible?'flex':'none';if(visible){spot.el.style.left=(v.x*.5+.5)*innerWidth+'px';spot.el.style.top=(-v.y*.5+.5)*innerHeight+'px'}}}
function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;render()})}
function lookAt(x,y,z){const d=new THREE.Vector3(x,y,z).sub(camera.position);yaw=Math.atan2(d.x,-d.z);pitch=Math.atan2(d.y,Math.hypot(d.x,d.z))}
function addSpot(pos,label,icon,action){const b=document.createElement('button');b.className='hotspot';b.setAttribute('aria-label',label);b.innerHTML=`<span class="spot-ring" data-icon="${icon}"></span><span class="spot-text">${label}</span>`;b.onclick=()=>onHotspot(action);spotLayer.append(b);spots.push({pos:new THREE.Vector3(...pos),el:b})}
function setScene(name){current=name;spots=[];spotLayer.replaceChildren();faces=null;signLayer.style.visibility='hidden';mountSigns(name);camera.position.set(...positions[name]);if(name==='exterior'){lookAt(0,5.1,0);addSpot([0,2.3,5.2],'Мектепке кіру','door','enter')}else if(name==='garden'){lookAt(-1,1.2,11);addSpot([-2.8,1.6,13],'Жағдаятты шешу','leaf','quest')}else{lookAt(0,name==='lobby'?2.9:2.6,-5);if(name==='lobby'){addSpot([5.5,2.6,-4.5],'Құқықтың 9 саласы','book','laws');addSpot([-7.1,2,-5.2],'Квестті бастау','play','start')}else addSpot([0,3.5,-4.7],'Жағдаятты шешу','book','quest');addSpot([0,2.4,11.5],'Мектеп картасы','map','map')}spotLayer.style.visibility='hidden';host.setAttribute('aria-busy','true');loadScene(name).then(loaded=>{if(current!==name)return;faces=loaded;signLayer.style.visibility='visible';host.setAttribute('aria-busy','false');spotLayer.style.visibility='visible';render()}).catch(()=>{host.setAttribute('aria-busy','false');onHotspot('imageerror')})}
host.addEventListener('pointerdown',e=>{if(drag)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};host.setPointerCapture(e.pointerId)});host.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;yaw-=(e.clientX-drag.x)*.0037;pitch=Math.max(-1.22,Math.min(1.22,pitch+(e.clientY-drag.y)*.0037));drag.x=e.clientX;drag.y=e.clientY;schedule()});for(const e of['pointerup','pointercancel','lostpointercapture'])host.addEventListener(e,event=>{if(drag?.id===event.pointerId){drag=null;schedule()}});
host.addEventListener('wheel',e=>{e.preventDefault();fov=THREE.MathUtils.clamp(fov+e.deltaY*.035,35,105);schedule()},{passive:false});window.addEventListener('resize',schedule);window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/INPUT|TEXTAREA/.test(e.target.tagName))return;let used=true;switch(e.key){case'ArrowLeft':yaw+=.13;break;case'ArrowRight':yaw-=.13;break;case'ArrowUp':pitch=Math.min(1.22,pitch+.1);break;case'ArrowDown':pitch=Math.max(-1.22,pitch-.1);break;default:used=false}if(used){e.preventDefault();schedule()}});
await loadScene('exterior');
return{setScene,turn(d){yaw+=d*.28;schedule()},zoom(d){fov=THREE.MathUtils.clamp(fov+d*6,35,105);schedule()},get current(){return current}};
}
